import React, { Component } from "react";
import "./Service.css";

export default class Service extends Component {
    constructor(props) {
        super(props);
        this.state = {
            servicepage: null,
            currentImageIndex: 0
        };
    }

    componentDidMount() {
        const pageName = "Service1";
        fetch(`http://localhost:3001/${pageName}`) 
            .then(response => response.json())
            .then(page => {
                this.setState({ servicepage: page });
            })
            .catch(error => console.error('Error fetching data:', error));
    }

    handleNextImage = () => {
        const { currentImageIndex } = this.state;
        // Assuming images are stored in an array called "images"
        if (currentImageIndex < images.length - 1) {
            this.setState({ currentImageIndex: currentImageIndex + 1 });
        }
    }

    handlePrevImage = () => {
        const { currentImageIndex } = this.state;
        if (currentImageIndex > 0) {
            this.setState({ currentImageIndex: currentImageIndex - 1 });
        }
    }

    render() {
        const { servicepage, currentImageIndex } = this.state;
        if (!servicepage) return <div>PAGE NOT FOUND</div>;
        const contentService = servicepage.content;
        // Assuming images are stored in an array called "images"
        const images = ["./media/dog1.png", "./media/dog2.png", "./media/dog3.png"];

        return (
            <div className="container">
                <div className="image-section" style={{ backgroundImage: `url(${images[currentImageIndex]})` }}>
                    <button onClick={this.handlePrevImage}>Previous</button>
                    <button onClick={this.handleNextImage}>Next</button>
                </div>     
                <div className="paw"></div>
                <div className="content-section">
                    <p className="Hello">{contentService[0]}</p>
                    <p className="Miss">{contentService[1]}</p>
                    <button type="submit" className="location">Pet's Location</button>
                </div>
            </div>
        );
    }
}
